#!/bin/bash
# SPDX-License-Identifier: MIT
# Usage: tests/build-t_vk_present.sh [native|aarch64|all]   Output: out/t_vk_present-<arch>
# Needs the xdg-shell protocol code generated by driver/present/build.sh (present/gen).
set -euo pipefail
cd "$(dirname "$0")/.."
G=../present/gen
[ -f $G/xdg-shell-protocol.c ] || (cd ../present && ./build.sh native >/dev/null)
CC_A64=${CC_A64:-$PWD/../../droidtest/tools/cc-aarch64-glibc}
CF="-std=gnu11 -O2 -Wall -Wextra -Wno-unused-parameter -I../third_party/mesa/include -I$G -DVK_USE_PLATFORM_WAYLAND_KHR"
SRC="tests/t_vk_present.c $G/xdg-shell-protocol.c"
mkdir -p out
what=${1:-aarch64}
if [ "$what" = native ] || [ "$what" = all ]; then ${CC:-cc} $CF -o out/t_vk_present-native $SRC -ldl -lm -lwayland-client; echo "built out/t_vk_present-native"; fi
if [ "$what" = aarch64 ] || [ "$what" = all ]; then "$CC_A64" $CF -o out/t_vk_present-aarch64 $SRC -ldl -lm -lwayland-client; llvm-strip -s out/t_vk_present-aarch64 2>/dev/null || true; echo "built out/t_vk_present-aarch64"; fi
